import React, { useState } from 'react';

/**
 * Add Community Event Form Component.
 * STRICT REQUIREMENT: No ID input field is present. ID is auto-generated by backend.
 * Student ID: 2400032700 | Name: UMMADI VIJAY KUMAR | Section: S51
 */
export default function AddEventForm({ onEventCreated, onCancel }) {
  const [formData, setFormData] = useState({
    eventName: '',
    venue: '',
    attendeeCount: '',
    completed: false,
  });

  const [errors, setErrors] = useState({});
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [serverError, setServerError] = useState(null);

  // Validate form inputs on frontend
  const validateField = (name, value) => {
    switch (name) {
      case 'eventName':
        if (!value || !value.trim()) return 'Event name is required';
        if (value.trim().length < 3) return 'Event name must be at least 3 characters long';
        if (value.trim().length > 100) return 'Event name cannot exceed 100 characters';
        return null;
      case 'venue':
        if (!value || !value.trim()) return 'Venue location is required';
        if (value.trim().length < 3) return 'Venue must be at least 3 characters long';
        if (value.trim().length > 150) return 'Venue cannot exceed 150 characters';
        return null;
      case 'attendeeCount':
        if (value === '' || value === null || value === undefined) return 'Attendee count is required';
        const num = Number(value);
        if (isNaN(num) || !Number.isInteger(num)) return 'Attendee count must be a valid whole number';
        if (num < 1) return 'Attendee count must be at least 1 person';
        if (num > 1000000) return 'Attendee count cannot exceed 1,000,000';
        return null;
      default:
        return null;
    }
  };

  const validateAll = () => {
    const newErrors = {};
    const nameErr = validateField('eventName', formData.eventName);
    if (nameErr) newErrors.eventName = nameErr;

    const venueErr = validateField('venue', formData.venue);
    if (venueErr) newErrors.venue = venueErr;

    const countErr = validateField('attendeeCount', formData.attendeeCount);
    if (countErr) newErrors.attendeeCount = countErr;

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleChange = (e) => {
    const { name, value, type, checked } = e.target;
    const fieldValue = type === 'checkbox' ? checked : value;

    setFormData((prev) => ({
      ...prev,
      [name]: fieldValue,
    }));

    // Real-time validation feedback
    if (errors[name]) {
      const fieldError = validateField(name, fieldValue);
      setErrors((prev) => ({
        ...prev,
        [name]: fieldError,
      }));
    }
  };

  const handleBlur = (e) => {
    const { name, value } = e.target;
    const fieldError = validateField(name, value);
    if (fieldError) {
      setErrors((prev) => ({ ...prev, [name]: fieldError }));
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setServerError(null);

    if (!validateAll()) {
      return;
    }

    setIsSubmitting(true);
    try {
      await onEventCreated(formData);
      // Reset form on success
      setFormData({
        eventName: '',
        venue: '',
        attendeeCount: '',
        completed: false,
      });
      setErrors({});
    } catch (err) {
      setServerError(err.message || 'Failed to create community event. Please verify backend service.');
      if (err.fieldErrors) {
        setErrors(err.fieldErrors);
      }
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleReset = () => {
    setFormData({
      eventName: '',
      venue: '',
      attendeeCount: '',
      completed: false,
    });
    setErrors({});
    setServerError(null);
  };

  return (
    <div className="custom-card p-4 mb-4">
      <div className="d-flex align-items-center justify-content-between pb-3 mb-3 border-bottom">
        <div className="d-flex align-items-center gap-2">
          <div className="rounded-3 bg-primary bg-opacity-10 text-primary p-2">
            <i className="bi bi-calendar-plus-fill fs-5"></i>
          </div>
          <div>
            <h5 className="fw-bold mb-0 text-dark">Add New Community Event</h5>
            <small className="text-muted">Enter details below to create a community event</small>
          </div>
        </div>
        {/* Visual confirmation badge regarding ID */}
        <span className="badge bg-light text-secondary border px-3 py-2 small">
          <i className="bi bi-shield-check text-success me-1"></i>
          ID: System Auto-Generated (No User Input)
        </span>
      </div>

      {serverError && (
        <div className="alert alert-danger d-flex align-items-center gap-2 alert-dismissible fade show" role="alert">
          <i className="bi bi-exclamation-triangle-fill fs-5"></i>
          <div>{serverError}</div>
          <button type="button" className="btn-close" onClick={() => setServerError(null)}></button>
        </div>
      )}

      <form onSubmit={handleSubmit} noValidate>
        <div className="row g-3">
          {/* Event Name */}
          <div className="col-12 col-md-6">
            <label htmlFor="eventName" className="form-label fw-semibold text-secondary small">
              Event Name <span className="text-danger">*</span>
            </label>
            <div className="input-group">
              <span className="input-group-text bg-light text-muted border-end-0">
                <i className="bi bi-tag-fill"></i>
              </span>
              <input
                type="text"
                className={`form-control border-start-0 ${errors.eventName ? 'is-invalid' : formData.eventName && !errors.eventName ? 'is-valid' : ''}`}
                id="eventName"
                name="eventName"
                placeholder="e.g., Clean Energy & Climate Workshop"
                value={formData.eventName}
                onChange={handleChange}
                onBlur={handleBlur}
                disabled={isSubmitting}
                maxLength={100}
              />
              {errors.eventName && <div className="invalid-feedback d-block">{errors.eventName}</div>}
            </div>
            <div className="d-flex justify-content-between mt-1">
              <small className="text-muted">Between 3 and 100 characters</small>
              <small className="text-muted">{formData.eventName.length}/100</small>
            </div>
          </div>

          {/* Venue */}
          <div className="col-12 col-md-6">
            <label htmlFor="venue" className="form-label fw-semibold text-secondary small">
              Venue Location <span className="text-danger">*</span>
            </label>
            <div className="input-group">
              <span className="input-group-text bg-light text-muted border-end-0">
                <i className="bi bi-geo-alt-fill text-danger"></i>
              </span>
              <input
                type="text"
                className={`form-control border-start-0 ${errors.venue ? 'is-invalid' : formData.venue && !errors.venue ? 'is-valid' : ''}`}
                id="venue"
                name="venue"
                placeholder="e.g., University Auditorium Hall B"
                value={formData.venue}
                onChange={handleChange}
                onBlur={handleBlur}
                disabled={isSubmitting}
                maxLength={150}
              />
              {errors.venue && <div className="invalid-feedback d-block">{errors.venue}</div>}
            </div>
            <div className="d-flex justify-content-between mt-1">
              <small className="text-muted">Between 3 and 150 characters</small>
              <small className="text-muted">{formData.venue.length}/150</small>
            </div>
          </div>

          {/* Attendee Count */}
          <div className="col-12 col-md-6">
            <label htmlFor="attendeeCount" className="form-label fw-semibold text-secondary small">
              Expected Attendee Count <span className="text-danger">*</span>
            </label>
            <div className="input-group">
              <span className="input-group-text bg-light text-muted border-end-0">
                <i className="bi bi-people-fill text-primary"></i>
              </span>
              <input
                type="number"
                className={`form-control border-start-0 ${errors.attendeeCount ? 'is-invalid' : formData.attendeeCount && !errors.attendeeCount ? 'is-valid' : ''}`}
                id="attendeeCount"
                name="attendeeCount"
                placeholder="e.g., 250"
                min="1"
                max="1000000"
                value={formData.attendeeCount}
                onChange={handleChange}
                onBlur={handleBlur}
                disabled={isSubmitting}
              />
              {errors.attendeeCount && <div className="invalid-feedback d-block">{errors.attendeeCount}</div>}
            </div>
            <small className="text-muted mt-1 d-block">Minimum 1 attendee, whole number</small>
          </div>

          {/* Completed Status Switch */}
          <div className="col-12 col-md-6">
            <label className="form-label fw-semibold text-secondary small">
              Event Status <span className="text-danger">*</span>
            </label>
            <div className="p-2 border rounded-3 bg-light d-flex align-items-center justify-content-between">
              <div className="d-flex align-items-center gap-2">
                <i className={`bi ${formData.completed ? 'bi-check2-circle text-success fs-5' : 'bi-hourglass-split text-primary fs-5'}`}></i>
                <div>
                  <div className="fw-bold small">{formData.completed ? 'Completed Event' : 'Upcoming Event'}</div>
                  <small className="text-muted">{formData.completed ? 'The event has taken place' : 'Scheduled / Still in progress'}</small>
                </div>
              </div>
              <div className="form-check form-switch fs-5 m-0">
                <input
                  className="form-check-input"
                  type="checkbox"
                  role="switch"
                  id="completed"
                  name="completed"
                  checked={formData.completed}
                  onChange={handleChange}
                  disabled={isSubmitting}
                />
              </div>
            </div>
          </div>
        </div>

        {/* Action Buttons */}
        <div className="d-flex align-items-center justify-content-end gap-2 mt-4 pt-3 border-top">
          {onCancel && (
            <button type="button" className="btn btn-outline-secondary px-3" onClick={onCancel} disabled={isSubmitting}>
              Cancel
            </button>
          )}
          <button type="button" className="btn btn-light border px-3" onClick={handleReset} disabled={isSubmitting}>
            <i className="bi bi-arrow-counterclockwise me-1"></i>
            Reset Form
          </button>
          <button type="submit" className="btn btn-primary-custom px-4 d-flex align-items-center gap-2" disabled={isSubmitting}>
            {isSubmitting ? (
              <>
                <span className="spinner-border spinner-border-sm" role="status" aria-hidden="true"></span>
                Saving Event...
              </>
            ) : (
              <>
                <i className="bi bi-cloud-arrow-up-fill"></i>
                Save Community Event
              </>
            )}
          </button>
        </div>
      </form>
    </div>
  );
}
